export function getRequireResolver(extensions: any, detectCyclesAndConditional: any, currentlyResolving: any, fs: any): {
    getWrappedIds: () => string[];
    isRequiredId: (id: any) => any;
    shouldTransformCachedModule({ id: parentId, resolvedSources, meta: { commonjs: parentMeta }, }: {
        id: any;
        resolvedSources: any;
        meta: {
            commonjs: any;
        };
    }): Promise<boolean>;
    resolveRequireSourcesAndUpdateMeta: (rollupContext: any) => (parentId: any, isParentCommonJS: any, parentMeta: any, sources: any) => Promise<{
        source: any;
        id: any;
        isCommonJS: any;
    }[]>;
    isCurrentlyResolving(source: any, parentId: any): any;
};
